// Loads the current long-lived token so it can be exchanged for a fresh one.
//
// Instagram long-lived tokens last 60 days, can only be refreshed once they are
// at least 24 hours old, and CANNOT be refreshed after they expire. Running
// this weekly keeps the token permanently rolling forward.
const fs = require('fs');
const path = require('path');

const QUEUE_PATH =
  $env.TS_CONTENT_QUEUE ||
  'C:\\work\\OneTradingSocial\\Website\\automation\\n8n\\content-queue.json';
const TOKEN_PATH = path.join(path.dirname(QUEUE_PATH), 'instagram-token.json');

let store = {};
try {
  store = JSON.parse(fs.readFileSync(TOKEN_PATH, 'utf8'));
} catch (err) {
  store = {};
}

const token = store.accessToken || $env.IG_ACCESS_TOKEN;
if (!token) {
  throw new Error(
    'No Instagram token to refresh. Complete the OAuth consent and set IG_ACCESS_TOKEN first (README step 8).'
  );
}

const ageHours = store.refreshedAt
  ? (Date.now() - Date.parse(store.refreshedAt)) / 3600000
  : 999;

// Meta rejects a refresh on a token younger than 24h. Skip rather than error.
const tooYoung = ageHours < 24;

return [
  {
    json: {
      token,
      tokenPath: TOKEN_PATH,
      tooYoung,
      ageHours: Math.round(ageHours),
      expiresAt: store.expiresAt || null
    }
  }
];

// Persists the refreshed token and decides whether a human needs to be told.
const fs = require('fs');

const res = $json;
const prev = $('Read Current Token').first().json;

let ok = false;
let message = '';
let expiresAt = prev.expiresAt;

if (res.error) {
  // Meta returns { error: { message, type, code } } on failure.
  const e = res.error;
  message =
    'Instagram token refresh FAILED: ' +
    (e.message || JSON.stringify(e)) +
    (prev.expiresAt ? ' — current token expires ' + prev.expiresAt : '') +
    '. If it expires, the OAuth consent must be redone by hand.';
} else if (res.access_token) {
  const seconds = Number(res.expires_in || 5184000);
  expiresAt = new Date(Date.now() + seconds * 1000).toISOString();

  const store = {
    accessToken: res.access_token,
    refreshedAt: new Date().toISOString(),
    expiresAt,
    expiresInDays: Math.round(seconds / 86400)
  };

  fs.writeFileSync(prev.tokenPath, JSON.stringify(store, null, 2), 'utf8');
  ok = true;
  message =
    'Instagram token refreshed. Valid for ' +
    store.expiresInDays +
    ' more days (until ' +
    expiresAt.slice(0, 10) +
    ').';
} else {
  message =
    'Instagram token refresh returned an unexpected response: ' +
    JSON.stringify(res).slice(0, 300);
}

// Warn while there is still time to act, not after the token is dead.
const daysLeft = expiresAt ? (Date.parse(expiresAt) - Date.now()) / 86400000 : null;
const needsAttention = !ok || (daysLeft !== null && daysLeft < 14);

return [
  {
    json: {
      ok,
      needsAttention,
      message,
      expiresAt,
      daysLeft: daysLeft === null ? null : Math.floor(daysLeft),
      notification: '<b>TradingSocial — Instagram token</b>\n\n' + message
    }
  }
];
